using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace WolvenKit.App.Services.Themes;

/// <summary>Type of an overridable resource.</summary>
public enum ThemeKeyKind
{
    /// <summary>A <c>Color</c> resource.</summary>
    Color,

    /// <summary>A <c>SolidColorBrush</c> resource.</summary>
    Brush
}

/// <summary>
/// One overridable color resource. Generated by tools/themes/generate_theme_keys.py.
/// </summary>
public sealed class ThemeKeyEntry
{
    public string Key { get; set; } = "";

    public string Group { get; set; } = "";

    public string DisplayName { get; set; } = "";

    /// <summary>
    /// The type of the resource in App.Styles.xaml. The actual type is re-checked at runtime.
    /// </summary>
    public ThemeKeyKind Kind { get; set; } = ThemeKeyKind.Color;

    /// <summary>
    /// SolidColorBrush resources defined as <c>Color="{StaticResource Key}"</c>.
    /// They must be regenerated when <see cref="Key"/> is overridden.
    /// </summary>
    public List<string>? DerivedBrushes { get; set; }
}

/// <summary>
/// The list of resource keys a theme can override (not a JSON Schema). Loaded from the embedded theme-keys.json.
/// </summary>
public sealed class ThemeKeyCatalog
{
    private const string EmbeddedResourceName = "WolvenKit.App.Resources.Themes.theme-keys.json";

    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNameCaseInsensitive = true,
        Converters = { new JsonStringEnumConverter() }
    };

    public List<ThemeKeyEntry> Entries { get; set; } = [];

    private Dictionary<string, ThemeKeyEntry>? _byKey;

    /// <summary>Adds a key discovered at runtime (e.g. Syncfusion theme brushes).</summary>
    public void AddEntry(ThemeKeyEntry entry)
    {
        if (Find(entry.Key) is not null)
        {
            return;
        }
        Entries.Add(entry);
        _byKey![entry.Key] = entry;
    }

    public ThemeKeyEntry? Find(string key)
    {
        _byKey ??= Entries.ToDictionary(e => e.Key, StringComparer.Ordinal);
        return _byKey.GetValueOrDefault(key);
    }

    public static ThemeKeyCatalog LoadEmbedded()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(EmbeddedResourceName)
                           ?? throw new FileNotFoundException($"Embedded resource {EmbeddedResourceName} not found");
        return JsonSerializer.Deserialize<ThemeKeyCatalog>(stream, s_options) ?? new ThemeKeyCatalog();
    }
}
